insert into public.standard (doc_id, strand_id, grade, code, code_type, source_system_id, level, parent_id, text, extra, source_url, display_order, needs_review, last_verified)
values
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 1, $txt$AB-G1-NUM-1$txt$, $txt$derived$txt$, $txt$MAT1-OI1-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students interpret and explain quantity to 100.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can quantity be communicated?","knowledge":"A numeral is a symbol or group of symbols used to represent a number. | The absence of quantity is represented by 0. || Counting can begin at any number. | Counting more than one object at a time is called skip counting. || Sharing involves partitioning a quantity into a certain number of groups. | Grouping involves partitioning a quantity into groups of a certain size. || Familiar arrangements of small quantities facilitate subitizing. || Comparisons of quantity can be described by using words such as | equal | not equal | less | more | Equality can be modelled by using a balance. | The equal sign, = , is used to show equality between two quantities. | The unequal sign, \\not = , is used to show that two quantities are not equal.","understanding":"Quantity is expressed in words and numerals based on patterns. | Quantity in the world is represented in multiple ways. || Each number counted includes all previous numbers (counting principle: hierarchical inclusion). | A quantity can be determined by counting more than one object in a set at a time. || Quantity can be partitioned by sharing or grouping. || A quantity can be perceived as the composition of smaller quantities. || Two quantities are equal when there is the same number of objects in both sets. | Equality is a balance between two quantities.","skills_procedures":"Represent quantities, using words, numerals, objects, or pictures. | Identify a quantity of 0 in familiar situations. || Count within 100, forward by 1s, starting at any number, according to the counting principles. | Count backward from 20 to 0 by 1s . | Skip count to 100, forward by 5s and 10s, starting at 0. | Skip count to 20, forward by 2s, starting at 0. || Partition a set of objects by sharing and grouping. | Demonstrate conservation of number when sharing or grouping. || Recognize quantities to 10. || Investigate equal and unequal quantities, including using a balance model. | Identify numbers that are one more, two more, one less, and two less than a given number. | Represent a quantity relative to another, including symbolically.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat1$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 1, $txt$AB-G1-NUM-2$txt$, $txt$derived$txt$, $txt$MAT1-OI1-GQ2-LO1$txt$, $txt$outcome$txt$, null, $txt$Students examine addition and subtraction within 20.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can addition and subtraction provide perspectives of number?","knowledge":"Quantities can be composed or decomposed to model a change in quantity. | Addition can be applied in various contexts, including | combining parts to find the whole | increasing an existing quantity | Subtraction can be applied in various contexts, including | comparing two quantities | taking away one quantity from another | finding a part of a whole | Addition and subtraction can be modelled by using a balance. || Strategies are meaningful steps taken to solve problems. | Addition and subtraction strategies include | counting on | counting back | decomposition | compensation | making tens | Sums and differences can be expressed symbolically by using the addition sign, + , the subtraction sign, - , and the equal sign, = . | The order in which two quantities are added does not affect the sum (commutative property). | The order in which two quantities are subtracted affects the difference. | Addition of 0 to any number, or subtraction of 0 from any number, results in the same number (zero property). | A missing quantity in a sum or difference can be represented in different ways, including | a + b = \\Box | a + \\Box = c | \\Box + b = c | e - f = \\Box | e - \\Box = g | \\Box - f = g || Addition and subtraction number facts represent part-part-whole relationships. | Fact families are groups of related addition and subtraction number facts.","understanding":"Addition and subtraction are processes that describe the composition and decomposition of quantity. || Addition and subtraction are opposite (inverse) mathematical operations. || Addition number facts have related subtraction number facts.","skills_procedures":"Visualize quantities between 10 and 20 as compositions of 10 and another quantity. | Model addition and subtraction within 20 in various ways, including with a balance. | Relate addition and subtraction to various contexts involving composition or decomposition of quantity. || Investigate addition and subtraction strategies. | Add numbers up to a sum of 20 and subtract numbers with a maximum minuend of 20. | Check differences and sums, using inverse operations. | Determine a missing quantity in a sum or difference, within 20, in a variety of ways. | Express addition and subtraction symbolically. | Solve problems, using addition and subtraction. || Identify patterns in addition and subtraction, including patterns in addition tables. | Recognize families of related addition and subtraction number facts. | Recall addition number facts, with addends to 10, and related subtraction number facts.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat1$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 1, $txt$AB-G1-NUM-3$txt$, $txt$derived$txt$, $txt$Xw6KTmlUXE-ROAWf_vqvfQ$txt$, $txt$outcome$txt$, null, $txt$Students examine one-half as a part-whole relationship.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"In what ways can parts and wholes be related?","knowledge":"One-half can be one of two equal groups or one of two equal pieces.","understanding":"In a quantity partitioned into two equal groups, each group represents one-half of the whole quantity. | In a shape or object partitioned into two identical pieces, each piece represents one-half of the whole.","skills_procedures":"Identify one-half in familiar situations. | Partition an even set of objects into two equal groups, limited to sets of 10 or less. | Partition a shape or object into two equal pieces. | Describe one of two equal groups or pieces as one-half. | Verify that the two halves of one whole group, shape, or object are the same size.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat1$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$GEO$txt$), 1, $txt$AB-G1-GEO-1$txt$, $txt$derived$txt$, $txt$MAT1-OI3-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students interpret shape in two and three dimensions.$txt$, $txt${"organizing_idea":"Geometry: Shapes are defined and related by geometric attributes.","guiding_question":"In what ways can shape be characterized?","knowledge":"Familiar two-dimensional shapes include | squares | circles | rectangles | triangles | Familiar three-dimensional shapes include | cubes | prisms | cylinders | spheres | pyramids | cones | A composite shape is composed of two or more shapes. | A line of symmetry indicates the division between the matching halves of a symmetrical shape.","understanding":"A shape can be modelled in various sizes and orientations. | A shape is symmetrical if it can be decomposed into matching halves.","skills_procedures":"Identify familiar shapes in various sizes and orientations. | Model two-dimensional shapes. | Sort shapes according to one attribute and describe the sorting rule. | Compose and decompose two- or three-dimensional composite shapes. | Identify familiar shapes within two- or three-dimensional composite shapes. | Investigate symmetry of two-dimensional shapes by folding and matching.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat1$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$MEA$txt$), 1, $txt$AB-G1-MEA-1$txt$, $txt$derived$txt$, $txt$MAT1-OI5-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students relate length to the understanding of size.$txt$, $txt${"organizing_idea":"Measurement: Attributes such as length, area, volume, and angle are quantified by measurement.","guiding_question":"In what ways can length provide perspectives of size?","knowledge":"Size may refer to the length of an object, including | height | width | depth | A length does not need to be a straight line. | The length between any two points in space is called distance. | Familiar contexts of distance include | distance between objects or people | distance between objects on the land | distance between home and school | distance between towns or cities || Indirect comparison is useful when objects are fixed in place or difficult to move. | Comparisons of size can be described by using words such as | higher | wider | deeper","understanding":"Length is a measurable attribute that describes the amount of fixed space between the end points of an object. | Length remains the same if an object is repositioned but may be named differently. || The size of two objects can be compared indirectly with a third object.","skills_procedures":"Recognize the height, width, or depth of an object as lengths in various orientations. | Compare and order objects according to length. | Describe distance in familiar contexts. || Compare the length, area, or capacity of two objects directly or indirectly by using a third object. | Order objects according to length, area, or capacity.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat1$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$PAT$txt$), 1, $txt$AB-G1-PAT-1$txt$, $txt$derived$txt$, $txt$MAT1-OI6-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students examine patterns in cycles.$txt$, $txt${"organizing_idea":"Patterns: Awareness of patterns supports problem solving in various situations.","guiding_question":"What can patterns communicate?","knowledge":"A cycle can express repetition of events or experiences. | Cycles include | seasons | day/night | life cycles | calendars | The same pattern can be represented with different elements. | A pattern core is a sequence of one or more elements that repeats as a unit.","understanding":"A pattern that appears to repeat may not be a cycle. | A cycle is a repeating pattern that repeats in the same way forever.","skills_procedures":"Recognize cycles encountered in daily routines and nature. | Investigate cycles found in nature that inform First Nations, Métis, or Inuit practices. | Identify the pattern core, up to four elements, in a cycle. | Identify a missing element in a repeating pattern or cycle. | Describe change and constancy in repeating patterns and cycles. | Create different representations of the same repeating pattern or cycle, limited to a pattern core of up to four elements. | Extend a sequence of elements in various ways to create repeating patterns.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat1$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$TIM$txt$), 1, $txt$AB-G1-TIM-1$txt$, $txt$derived$txt$, $txt$MAT1-OI7-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students explain time in relation to cycles.$txt$, $txt${"organizing_idea":"Time: Duration is described and quantified by time.","guiding_question":"How can time characterize change?","knowledge":"Time can be perceived through observable change. | First Nations, Métis, and Inuit experience time through sequences and cycles in nature, including cycles of seasons. | Cycles from a calendar include days of the week and months of the year.","understanding":"Time is an experience of change. | Time can be perceived as a cycle.","skills_procedures":"Describe cycles of time encountered in daily routines and nature. | Describe observable changes that indicate a cycle of time. | Relate cycles of seasons to First Nations, Métis, or Inuit practices. | Identify cycles from a calendar.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat1$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$STA$txt$), 1, $txt$AB-G1-STA-1$txt$, $txt$derived$txt$, $txt$MAT1-OI8-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students investigate and represent data.$txt$, $txt${"organizing_idea":"Statistics: The science of collecting, analyzing, visualizing, and interpreting data can inform understanding and decision making.","guiding_question":"How can data be used to answer questions about the world?","knowledge":"Data can be collected information. || A graph is a visual representation of data. | A graph can represent data by using objects, pictures, or numbers.","understanding":"Data can be answers to questions. || Data can be represented in a graph.","skills_procedures":"Share wonderings about people, things, events, or experiences. | Gather data by sharing answers to questions. || Collaborate to construct a concrete graph, using data collected in the learning environment. | Create a pictograph from a concrete graph.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat1$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 2, $txt$AB-G2-NUM-1$txt$, $txt$derived$txt$, $txt$MAT2-OI1-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze quantity to 1000.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can quantity contribute to a sense of number?","knowledge":"Any number of objects in a set can be represented by a natural number: 0, 1, 2, 3…. | The values of the places in a three-digit natural number are hundreds, tens, and ones. | Places that have no value within a given number use zero as a placeholder. | The number line is a spatial representation of quantity. || A quantity can be skip counted in various ways according to context. | Quantities of money can be skip counted in amounts that are represented by coins and bills (denominations). || An even quantity will have no remainder when partitioned into two equal groups or groups of two. | An odd quantity will have a remainder of one when partitioned into two equal groups or groups of two. || A benchmark is a known quantity to which another quantity can be compared. || Words that can describe a comparison between two unequal quantities include | not equal | greater than | less than | The less than sign, < , and the greater than sign, > , are used to indicate inequality between two quantities. | Equality and inequality can be modelled by using a balance.","understanding":"There are infinitely many natural numbers. | Every digit in a natural number has a value based on its place. | Each natural number is associated with exactly one point on the number line. || A quantity can be interpreted as a composition of groups. || All natural numbers are either even or odd. || A quantity can be estimated when an exact count is not needed. || Inequality is an imbalance between two quantities.","skills_procedures":"Represent quantities, using words and natural numbers. | Identify the digits representing hundreds, tens, and ones based on place in a natural number. | Relate a number, including zero, to its position on the number line. || Decompose quantities into groups of 100s, 10s, and 1s. | Count within 1000, forward and backward by 1s, starting at any number. | Skip count by 20s, 25s, or 50s, starting at 0. | Skip count by 2s and 10s, starting at any number. | Determine the value of a collection of coins or bills of the same denomination by skip counting. || Model even and odd quantities by sharing and grouping. | Describe a quantity as even or odd. | Partition a set of objects by sharing or grouping, with or without remainders. || Estimate quantities, using benchmarks. || Model equality and inequality between two quantities, including with a balance. | Compare and order natural numbers. | Describe a quantity as less than, greater than, or equal to another quantity.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat2$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 2, $txt$AB-G2-NUM-2$txt$, $txt$derived$txt$, $txt$MAT2-OI1-GQ2-LO1$txt$, $txt$outcome$txt$, null, $txt$Students investigate addition and subtraction within 100.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can addition and subtraction be interpreted?","knowledge":"The order in which more than two numbers are added does not affect the sum (associative property). || Familiar addition and subtraction number facts facilitate addition and subtraction strategies. | Addition and subtraction strategies for two-digit numbers include making multiples of ten and using doubles.","understanding":"A sum can be composed in multiple ways. || Addition and subtraction can represent the sum or difference of countable quantities or measurable lengths.","skills_procedures":"Visualize 100 as a composition of multiples of 10 in various ways. | Compose a sum in multiple ways, including with more than two addends. || Recall and apply addition number facts, with addends to 10, and related subtraction number facts. | Investigate strategies for addition and subtraction of two-digit numbers. | Add numbers up to a sum of 100 and subtract numbers with a maximum minuend of 100. | Verify a sum or difference, using inverse operations. | Determine a missing quantity in a sum or difference, within 100, in a variety of ways. | Solve problems, using addition and subtraction of countable quantities or measurable lengths.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat2$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 2, $txt$AB-G2-NUM-3$txt$, $txt$derived$txt$, $txt$-Aw3R3Gn50ibzZJGbi-Sag$txt$, $txt$outcome$txt$, null, $txt$Students interpret part-whole relationships, using unit fractions.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"In what ways can parts compose a whole?","knowledge":"A whole can be a whole set of objects or a whole object that can be partitioned into a number of equal parts. | The whole can be any size and is designated by context. | A unit fraction describes any one of the equal parts that compose a whole.","understanding":"Fractions can represent part-to-whole relationships. | One whole can be interpreted as a number of unit fractions.","skills_procedures":"Model a unit fraction by partitioning a whole object or whole set into equal parts, limited to 10 or fewer equal parts. | Compare different unit fractions of the same whole, limited to denominators of 10 or less. | Compare the same unit fractions of different wholes, limited to denominators of 10 or less. | Model one whole, using a given unit fraction, limited to denominators of 10 or less.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat2$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$GEO$txt$), 2, $txt$AB-G2-GEO-1$txt$, $txt$derived$txt$, $txt$MAT2-OI3-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze and explain geometric attributes of shape.$txt$, $txt${"organizing_idea":"Geometry: Shapes are defined and related by geometric attributes.","guiding_question":"How can shape influence perception of space?","knowledge":"Common geometric attributes include | sides | vertices | faces or surfaces | Two-dimensional shapes may have sides that are line segments. | Three-dimensional shapes may have faces that are two-dimensional shapes. || A shape can change orientation or position through slides (translations), turns (rotations), or flips (reflections). | Shapes can be turned or flipped in the creation of art.","understanding":"Shapes are defined according to geometric attributes. | A shape can be visualized as a composition of other shapes. || Geometric attributes do not change when a shape is translated, rotated, or reflected.","skills_procedures":"Sort shapes according to two geometric attributes and describe the sorting rule. | Relate the faces of three-dimensional shapes to two-dimensional shapes. | Create a picture or design with shapes from verbal instructions, visualization, or memory. || Investigate translation, rotation, and reflection of two- and three-dimensional shapes. | Describe geometric attributes of two- and three-dimensional shapes in various orientations. | Recognize the translation, rotation, or reflection of shapes represented in artwork.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat2$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$MEA$txt$), 2, $txt$AB-G2-MEA-1$txt$, $txt$derived$txt$, $txt$MAT2-OI5-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students communicate length, using units.$txt$, $txt${"organizing_idea":"Measurement: Attributes such as length, area, volume, and angle are quantified by measurement.","guiding_question":"How can length contribute to interpretations of space?","knowledge":"Tiling is the process of measuring a length by using many copies of a unit without gaps or overlaps. | Iterating is the process of measuring a length by repeating one copy of a unit without gaps or overlaps. | The unit can be chosen based on the length to be measured. | Length can be measured with non-standard units or standard units. | Non-standard units found in nature can be used to measure length on the land. | Standard units, such as centimetres, can enable a common language around measurement. || A referent is a personal or familiar representation of a known length. | A common referent from the land or body parts can be used to measure length.","understanding":"Length is quantified by measurement. | Length is measured with equal-sized units that themselves have length. | The number of units required to measure a length is inversely related to the size of the unit. || Length can be estimated when a measuring tool is not available.","skills_procedures":"Measure length with non-standard units by tiling, iterating, or using a self-created measuring tool. | Compare and order measurements of different lengths measured with the same non-standard units, and explain the choice of units. | Compare measurements of the same length measured with different non-standard units. | Measure length with standard units by tiling or iterating with a centimetre. | Compare and order measurements of different lengths measured with centimetres. || Identify referents for a centimetre. | Estimate length by visualizing the iteration of a referent for a centimetre. | Investigate First Nations, Métis, or Inuit use of the land in estimations of length.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat2$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$PAT$txt$), 2, $txt$AB-G2-PAT-1$txt$, $txt$derived$txt$, $txt$MAT2-OI6-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students explain and analyze patterns in a variety of contexts.$txt$, $txt${"organizing_idea":"Patterns: Awareness of patterns supports problem solving in various situations.","guiding_question":"How can patterns characterize change?","knowledge":"Change can be an increase or a decrease in the number and size of elements. | A hundreds chart is an arrangement of natural numbers that illustrates multiple patterns. | Patterns can be found and created in cultural designs. || Attributes of elements, such as size and colour, can contribute to a pattern.","understanding":"A pattern can show increasing or decreasing change. | A pattern is more evident when the elements are represented, organized, aligned, or oriented in familiar ways. || A pattern core can vary in complexity.","skills_procedures":"Describe non-repeating patterns encountered in surroundings, including in art, architecture, cultural designs, and nature. | Investigate patterns in a hundreds chart. | Create increasing patterns, using sounds, objects, pictures, or actions. || Create and express a repeating pattern with a pattern core of up to four elements that change by more than one attribute.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat2$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$TIM$txt$), 2, $txt$AB-G2-TIM-1$txt$, $txt$derived$txt$, $txt$MAT2-OI7-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students relate duration to time.$txt$, $txt${"organizing_idea":"Time: Duration is described and quantified by time.","guiding_question":"How can duration support interpretation of time?","knowledge":"Events can be related to calendar dates. | Duration can be described by using comparative language such as longer or shorter. | Duration can be measured in non-standard units, including events, natural cycles, or personal referents. | Winter counts are First Nations symbolic calendars that record oral traditions and significant events. || Time can be described by using standard units.","understanding":"Time can be communicated in various ways. | Duration is the measure of an amount of time from beginning to end. || Duration is quantified by measurement.","skills_procedures":"Express significant events, using calendar dates. | Describe the duration between or until significant events, using comparative language. | Describe the duration of events, using non-standard units. | Relate First Nations’ winter counts to duration. || Describe the relationship between days, weeks, months, and years. | Describe the duration between or until significant events, using standard units of time.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat2$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$STA$txt$), 2, $txt$AB-G2-STA-1$txt$, $txt$derived$txt$, $txt$MAT2-OI8-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students relate data to a variety of representations.$txt$, $txt${"organizing_idea":"Statistics: The science of collecting, analyzing, visualizing, and interpreting data can inform understanding and decision making.","guiding_question":"How can data inform representation?","knowledge":"Data can be collected by asking questions. | First-hand data is data collected by the person using the data. || Data can be recorded by using tally marks, words, or counts. | Data can be expressed through First Nations, Métis, or Inuit stories. | A graph includes features such as | a title | a legend | axes | axis labels | Data can be represented with graphs, such as | pictographs | bar graphs | dot plots","understanding":"Data can be collected to answer questions. || Data can be represented in various ways.","skills_procedures":"Generate questions for a specific investigation within the learning environment. | Collect first-hand data by questioning people within the learning environment. || Record data in a table. | Construct graphs to represent data. | Interpret graphs to answer questions. | Compare the features of pictographs, dot plots, and bar graphs.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat2$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 3, $txt$AB-G3-NUM-1$txt$, $txt$derived$txt$, $txt$MAT3-OI1-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students interpret place value to 100 000.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can place value support organization of number?","knowledge":"For numbers in base-10, each place has 10 times the value of the place to its right. | The digits 0 to 9 indicate the number of groups in each place in a number. | The value of each place in a number is the product of the digit and its place value. | Numbers can be composed in various ways by using place value. | Numbers can be rounded in contexts where an exact count is not needed. | The less than sign, < , and the greater than sign, > , are used to show the relationship between two unequal numbers. | A zero in the leftmost place of a natural number does not change the value of the number. | The dollar sign, $, is placed to the left of the dollar value in English and to the right of the dollar value in French. | The cent sign, ﻿¢, is placed to the right of the cent value in English and in French.","understanding":"Place value is the basis for the base-10 system. | Place value determines the value of a digit based on its place in a number relative to the ones place. | Place value is used to read, write, and compare numbers.","skills_procedures":"Identify the place value of each digit in a natural number. | Relate the values of adjacent places. | Determine the value of each digit in a natural number. | Express natural numbers, using words and numerals. | Express various compositions of a natural number, using place value. | Round natural numbers to various places. | Compare and order natural numbers. | Express the relationship between two numbers, using < , > , or = . | Count and represent the value of a collection of nickels, dimes, and quarters as cents. | Count and represent the value of a collection of loonies, toonies, and bills as dollars. | Recognize French and English symbolic representations of monetary values.","source_last_modified":"2025-05-30","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 3, $txt$AB-G3-NUM-2$txt$, $txt$derived$txt$, $txt$MAT3-OI1-GQ2-LO1$txt$, $txt$outcome$txt$, null, $txt$Students apply strategies for addition and subtraction within 1000.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can processes be established for addition and subtraction?","knowledge":"Recall of addition and subtraction number facts facilitates addition and subtraction strategies. | Standard algorithms for addition and subtraction are conventional procedures based on place value. | Estimation can be used to support addition and subtraction in everyday situations, including | when an exact sum or difference is not needed | to check if an answer is reasonable","understanding":"Addition and subtraction strategies can be chosen based on the nature of the numbers. | Standard algorithms for addition and subtraction may be used for any natural numbers.","skills_procedures":"Relate strategies for the addition and subtraction of two-digit numbers to strategies for the addition and subtraction of three-digit numbers. | Model regrouping by place value for addition and subtraction. | Explain the standard algorithms for addition and subtraction of natural numbers. | Add and subtract natural numbers, using standard algorithms. | Estimate sums and differences. | Solve problems, using addition and subtraction.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 3, $txt$AB-G3-NUM-3$txt$, $txt$derived$txt$, $txt$MAT3-OI1-GQ3-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze and apply strategies for multiplication and division within 100.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can multiplication and division provide new perspectives of number?","knowledge":"Multiplication and division are inverse mathematical operations. | Multiplication can represent repeated addition. | Multiplication can be interpreted in various ways according to context, such as | equal groups | an array | an area | Division can be interpreted in various ways according to context, such as | equal sharing | equal grouping | repeated subtraction | The order in which two quantities are multiplied does not affect the product (commutative property). | The order in which two numbers are divided affects the quotient. | Multiplication or division by 1 results in the same number (identity property). || Numbers can be multiplied or divided in parts (distributive property). | Multiplication strategies include | repeated addition | multiplying in parts | compensation | Division strategies include | repeated subtraction | partitioning the dividend | Products can be expressed symbolically by using the multiplication sign, \\times , factors, and the equal sign. | Quotients can be expressed symbolically by using the division sign, \\div , dividend, divisor, and the equal sign. | A missing quantity in a product or quotient can be represented in different ways, including | a \\times b = \\Box | a \\times \\Box = c | \\Box \\times b = c | e \\div f = \\Box | e \\div \\Box = g | \\Box \\div f = g | A remainder is the quantity left over after division. || A multiplication table shows both multiplication and division facts. | Fact families are groups of related multiplication and division number facts.","understanding":"Quantities can be composed and decomposed through multiplication and division. || Sharing and grouping situations can be interpreted as multiplication or division. | Multiplication and division strategies can be supported by addition and subtraction. || Multiplication number facts have related division facts.","skills_procedures":"Compose a product, using equal groups of objects. | Relate multiplication to repeated addition. | Relate multiplication to skip counting. | Investigate multiplication by 0. | Model a quotient by partitioning a quantity into equal groups or groups of a certain size, with or without remainders. | Visualize and model products and quotients as arrays. | Recognize interpretations of multiplication and division in various contexts. || Investigate multiplication and division strategies. | Multiply numbers up to a product of 100 and divide numbers with a maximum dividend of 100. | Verify a product or quotient, using inverse operations. | Determine a missing quantity in a product or quotient in a variety of ways. | Express multiplication and division symbolically. | Explain the meaning of the remainder in various situations. | Solve problems, using multiplication and division in sharing or grouping situations. || Examine patterns in multiplication and division, including patterns in multiplication tables and skip counting. | Recognize families of related multiplication and division number facts. | Recall multiplication number facts, with factors to 10, and related division facts.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 3, $txt$AB-G3-NUM-4$txt$, $txt$derived$txt$, $txt$CLrkTvQMl0Oj1FGsDZHeJQ$txt$, $txt$outcome$txt$, null, $txt$Students interpret fractions in relation to one whole.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can fractions contribute to a sense of number?","knowledge":"The same fraction can represent | equal parts of one whole length, shape, or object | equal groups of one whole quantity | equal parts of each equal group in one whole quantity | The name of a fraction describes its composition as a number of unit fractions. | Fraction notation, (\\frac{a}{b}) , relates the numerator, a , a number of equal parts, to the denominator, b , the total number of equal parts in the whole. | Equal numerators or equal denominators can facilitate the comparison of fractions. | A fraction with a numerator that is equal to its denominator is one whole. | Each fraction is associated with a point on the number line.","understanding":"Fractions are numbers between natural numbers. | Fractions can represent part-to-whole relationships. | A unit fraction describes the size of the equal parts of a fraction. | The size of the parts and the total number of equal parts in the whole are inversely related.","skills_procedures":"Model fractions of a whole quantity, length, shape, or object, in various ways, limited to denominators of 12 or less. | Visualize fractions as compositions of a unit fraction. | Identify the numerator and denominator of a fraction in various representations. | Name a given fraction. | Express fractions, including one whole, symbolically, limited to denominators of 12 or less. | Relate various representations of the same fraction, limited to denominators of 12 or less. | Compare the same fraction of different-sized wholes. | Compare different fractions of the same whole that have the same denominator. | Compare different fractions of the same whole that have the same numerator and different denominators. | Express the relationship between two fractions of the same whole, using < , > , or = . | Relate a fraction less than one to its position on the number line, limited to denominators of 12 or less. | Compare fractions to benchmarks of 0, \\frac{1}{2} , and 1.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$ALG$txt$), 3, $txt$AB-G3-ALG-1$txt$, $txt$derived$txt$, $txt$MAT3-OI2-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students illustrate equality with equations.$txt$, $txt${"organizing_idea":"Algebra: Equations express relationships between quantities.","guiding_question":"How can equality facilitate agility with number?","knowledge":"An equation uses the equal sign to indicate equality between two expressions. | The left and right sides of an equation are interchangeable. || Equations can be modelled by using a balance. | A symbol may represent an unknown value in an equation.","understanding":"Two expressions are equal if they represent the same number. || Equations can have unknown values.","skills_procedures":"Write equations that represent equality between a number and an expression or between two different expressions of the same number. || Model equations that include an unknown value, including with a balance. | Determine an unknown value on the left or right side of an equation, limited to equations with one operation. | Solve problems, using equations, limited to equations with one operation.","source_last_modified":"2025-05-30","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$GEO$txt$), 3, $txt$AB-G3-GEO-1$txt$, $txt$derived$txt$, $txt$MAT3-OI3-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students relate geometric properties to shape.$txt$, $txt${"organizing_idea":"Geometry: Shapes are defined and related by geometric attributes.","guiding_question":"In what ways might geometric properties refine interpretation of shape?","knowledge":"Geometric properties can describe relationships, including perpendicular, parallel, and equal. | Parallel lines or planes are always the same distance apart. | Perpendicular lines or planes intersect at a 90﻿° (right) angle. | Right angles can be identified by using various referents, such as | the corner of a piece of paper | the angle between the hands on an analog clock at 3:00 | a capital letter L | Polygons include | triangles | quadrilaterals | pentagons | hexagons | octagons | Regular polygons have sides of equal length and interior angles of equal measure. || Transformations include | translations | rotations | reflections | The distance between any two vertices of a shape is maintained in the image created by a transformation.","understanding":"Geometric properties are relationships between geometric attributes. | Geometric properties define a class of polygon. || Geometric properties do not change when a polygon undergoes a transformation.","skills_procedures":"Investigate the relationships between the sides of a polygon, including perpendicular, parallel, and equal, using referents for 90° or by measuring. | Investigate the relationships between vertices of a polygon, including equal or right angles, using direct comparison or referents for 90°. | Describe geometric properties of regular and irregular polygons. | Sort polygons according to geometric properties and describe the sorting rule. | Classify polygons as regular or irregular, using geometric properties. || Examine geometric properties of polygons by translating, rotating, or reflecting, using hands-on materials or digital applications.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$MEA$txt$), 3, $txt$AB-G3-MEA-1$txt$, $txt$derived$txt$, $txt$MAT3-OI5-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students determine length, using standard units.$txt$, $txt${"organizing_idea":"Measurement: Attributes such as length, area, volume, and angle are quantified by measurement.","guiding_question":"In what ways can length be communicated?","knowledge":"The basic unit of length in the metric system is the metre. | Metric units are named by using prefixes that indicate the relationship to the basic unit, including | milli: one thousand millimetres in one metre | centi: one hundred centimetres in one metre | deci: ten decimetres in one metre | Metric units are abbreviated for convenience, including | m: metre | dm: decimetre | cm: centimetre | mm: millimetre | Standard measuring tools show iterations of a standard unit from an origin. | Units of length in the imperial system include inch, foot, and yard, related in these ways: | 12 inches in one foot | 36 inches in one yard | 3 feet in one yard | Approximate conversions between metric and imperial are useful in real-world situations, including | 2 \\frac{1}{2} centimetres are approximately 1 inch | 1 metre is approximately 3 feet | 30 centimetres are approximately 1 foot | 1 metre is approximately 1 yard || The perimeter of a polygon is the sum of the lengths of its sides. || A benchmark is a known length to which another length can be compared. | Length can be estimated by using a personal or familiar referent.","understanding":"Length is measured in standard units according to the metric system and the imperial system. | Length can be expressed in various units according to context and desired precision. || Length remains the same when decomposed or rearranged. || Length can be estimated when less accuracy is required.","skills_procedures":"Relate millimetres, centimetres, and metres. | Relate inches to feet and yards. | Justify the choice of millimetres, centimetres, or metres to measure various lengths. | Measure lengths of straight lines and curves, with millimetres, centimetres, or metres. | Recognize length expressed in metric or imperial units. | Approximate a measurement in inches, feet, or yards, using centimetres or metres. || Determine the perimeter of polygons. | Determine the length of an unknown side, given the perimeter of a polygon. || Identify referents for a centimetre and a metre. | Estimate length by comparing to a benchmark. | Estimate length by visualizing the iteration of a referent for a centimetre or metre.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$MEA$txt$), 3, $txt$AB-G3-MEA-2$txt$, $txt$derived$txt$, $txt$Fw_y7H1B706duQqzDkWglA$txt$, $txt$outcome$txt$, null, $txt$Students interpret angles.$txt$, $txt${"organizing_idea":"Measurement: Attributes such as length, area, volume, and angle are quantified by measurement.","guiding_question":"How can angles broaden an understanding of space?","knowledge":"Angle defines the space in | corners | bends | turns or rotations | intersections | slopes | The arms of an angle can be line segments or rays. | A vertex is the common end point of two arms. || Superimposing is the process of placing one angle over another to compare angles. | A referent is a personal or familiar representation of a known angle.","understanding":"An angle is formed when two arms meet at a vertex. | An angle can be interpreted as the motion of a length rotated about a vertex. || Two angles can be compared directly or indirectly.","skills_procedures":"Recognize various angles in surroundings. | Recognize situations in which an angle can be perceived as motion. || Compare two angles directly by superimposing. | Compare two angles indirectly by superimposing a third angle. | Estimate which of two angles is greater. | Identify referents for 90°. | Identify 90° angles in the environment, using a referent.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$PAT$txt$), 3, $txt$AB-G3-PAT-1$txt$, $txt$derived$txt$, $txt$MAT3-OI6-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze patterns in numerical sequences.$txt$, $txt${"organizing_idea":"Patterns: Awareness of patterns supports problem solving in various situations.","guiding_question":"How can diverse representations of patterns contribute to interpretation of change?","knowledge":"Ordinal numbers can indicate position in a sequence. | Finite sequences, such as a countdown, have a definite end. | Infinite sequences, such as the natural numbers, never end. || Numerical sequences can be constructed by using addition, subtraction, multiplication, or division.","understanding":"A sequence is a list of terms arranged in a certain order. | Sequences may be finite or infinite. || A sequence can progress according to a pattern.","skills_procedures":"Recognize familiar numerical sequences, including the sequence of even or odd numbers. | Describe position in a sequence, using ordinal numbers. | Differentiate between finite and infinite sequences. || Recognize skip-counting sequences in various representations, including rows or columns of a multiplication table. | Determine any missing term in a skip-counting sequence, using multiplication. | Describe the change from term to term in a numerical sequence, using mathematical operations.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$TIM$txt$), 3, $txt$AB-G3-TIM-1$txt$, $txt$derived$txt$, $txt$MAT3-OI7-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students tell time, using clocks.$txt$, $txt${"organizing_idea":"Time: Duration is described and quantified by time.","guiding_question":"How can duration be communicated?","knowledge":"Clocks relate seconds to minutes and hours according to a base-60 system. | The basic unit of time is the second. | One second is \\frac{1}{60} of a minute. | One minute is \\frac{1}{60} of an hour. | Analog and digital clocks represent time of day. | Time of day can be expressed as a duration relative to 12:00 in two 12-hour cycles. | Time of day can be expressed as a duration relative to 0:00 in one 24-hour cycle in some contexts, including French-language contexts.","understanding":"Clocks are standard measuring tools used to communicate time.","skills_procedures":"Investigate relationships between seconds, minutes, and hours, using an analog clock. | Relate minutes past the hour to minutes until the next hour. | Describe time of day as a.m. or p.m. relative to 12-hour cycles of day and night. | Tell time, using analog and digital clocks. | Express time of day in relation to one 24-hour cycle.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$STA$txt$), 3, $txt$AB-G3-STA-1$txt$, $txt$derived$txt$, $txt$MAT3-OI8-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students interpret and explain representations of data.$txt$, $txt${"organizing_idea":"Statistics: The science of collecting, analyzing, visualizing, and interpreting data can inform understanding and decision making.","guiding_question":"How can representation support communication?","knowledge":"Statistical questions are questions that can be answered by collecting data. || First-hand data is collected by the person using the data. | Second-hand data is data collected by others from sources such as websites and social media.","understanding":"Representation connects data to a statistical question. || Representation expresses data specific to a unique time and place. | Representation tells a story about data.","skills_procedures":"Formulate statistical questions for investigation. | Predict the answer to a statistical question. || Collect data, using digital or non-digital tools and resources. | Represent first-hand and second-hand data in a dot plot or bar graph with one-to-one correspondence. | Describe the story that a representation tells about a collection of data in relation to a statistical question. | Examine First Nations, Métis, or Inuit representations of data. | Consider possible answers to a statistical question based on the data collected.","source_last_modified":"2025-05-30","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat3$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 4, $txt$AB-G4-NUM-1$txt$, $txt$derived$txt$, $txt$MAT4-OI1-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students apply place value to decimal numbers.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can place value facilitate interpretation of number?","knowledge":"For numbers in base-10 , each place has one-tenth the value of the place to its left. | Multiplying or dividing a number by 10 corresponds to shifting place value one position to the left or right, respectively. | The decimal separator is a point in English and a comma in French. | Numbers, including decimal numbers, can be composed in various ways by using place value. | A zero placed to the right of the last digit in a decimal number does not change the value of the number. | The word and is used to indicate the decimal point when reading a number.","understanding":"Decimal numbers are numbers between natural numbers. | Decimal numbers are fractions with denominators of 10, 100, etc. | The separation between wholes and parts, including dollars and cents, can be represented by using decimal notation. | Patterns in place value are used to read and write numbers, including wholes and parts.","skills_procedures":"Identify the place value of each digit in a number, including tenths and hundredths. | Relate the values of adjacent places, including tenths and hundredths. | Determine the value of each digit in a number, including tenths and hundredths. | Express numbers, including decimal numbers, using words and numerals. | Express various compositions of a number, including decimal numbers, using place value. | Recognize decimal notation expressed in English and in French. | Round numbers to various places, including tenths. | Compare and order numbers, including decimal numbers. | Express the relationship between two numbers, including decimal numbers, using < , > , or = . | Express a monetary value in cents as a monetary value in dollars, using decimal notation.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 4, $txt$AB-G4-NUM-2$txt$, $txt$derived$txt$, $txt$MAT4-OI1-GQ2-LO1$txt$, $txt$outcome$txt$, null, $txt$Students add and subtract within 10 000, including decimal numbers to hundredths.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can understanding of addition and subtraction be extended to decimal numbers?","knowledge":"Standard algorithms for addition and subtraction of decimal numbers are conventional procedures based on place value. | Estimation can be used to check the reasonableness of a sum or difference.","understanding":"Standard algorithms for addition and subtraction may be used for any decimal numbers.","skills_procedures":"Add and subtract numbers, including decimal numbers, using standard algorithms. | Assess the reasonableness of a sum or difference, using estimation. | Solve problems, using addition and subtraction, including problems involving money.","source_last_modified":"2025-12-22","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 4, $txt$AB-G4-NUM-3$txt$, $txt$derived$txt$, $txt$MAT4-OI1-GQ3-LO1$txt$, $txt$outcome$txt$, null, $txt$Students explain properties of prime and composite numbers, using multiplication and division.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can multiplication and division characterize the composition of numbers?","knowledge":"A factor of a number is a divisor of that number. | A number is a multiple of any of its factors. | A prime number has factors of only itself and one. | A composite number has factors other than one and itself. | Zero and one are neither prime nor composite numbers.","understanding":"Different factors can compose the same product. | Different products can share factors. | A number divided by one of its factors will result in a remainder of 0.","skills_procedures":"Determine the factors of a number within 100 . | Describe a number as prime or composite. | Determine the first five multiples of a given number within 100. | Recognize the greatest common factor (greatest common divisor) of two numbers within 100.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 4, $txt$AB-G4-NUM-4$txt$, $txt$derived$txt$, $txt$MAT4-OI1-GQ4-LO1$txt$, $txt$outcome$txt$, null, $txt$Students multiply and divide natural numbers within 10 000.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can multiplication and division be interpreted?","knowledge":"Recall of multiplication and division number facts facilitates multiplication and division strategies. | Standard algorithms facilitate multiplication and division of natural numbers that have multiple digits. | Estimation can be used to check the reasonableness of a product or quotient.","understanding":"Multiplication and division strategies can be chosen based on the nature of the numbers.","skills_procedures":"Recall and apply multiplication number facts, with factors to 12, and related division number facts. | Investigate patterns in multiplication and division of natural numbers by 10, 100, and 1000. | Multiply and divide 3-digit natural numbers by 1-digit natural numbers, using personal strategies. | Examine standard algorithms for multiplication and division. | Multiply and divide 3-digit natural numbers by 1-digit natural numbers, using standard algorithms. | Divide and express a quotient with or without a remainder. | Investigate strategies for estimation of products and quotients. | Assess the reasonableness of a product or quotient, using estimation. | Solve problems, using multiplication and division.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 4, $txt$AB-G4-NUM-5$txt$, $txt$derived$txt$, $txt$MAT4-OI1-GQ5-LO1$txt$, $txt$outcome$txt$, null, $txt$Students apply equivalence to the interpretation of fractions.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can fractions be characterized in different ways?","knowledge":"Equivalent fractions are associated with the same point on the number line. | Equivalent fractions can be created by partitioning each equal part of a fraction in the same way. | Partitioning a fraction can be interpreted as multiplying the numerator and denominator of a fraction by the same number. | A fraction can be simplified to an equivalent form by dividing the numerator and denominator by a common factor. | The numerator and denominator of a fraction in simplest form have no common factors. | Dividing the numerator and denominator of a fraction by their greatest common factor will achieve simplest form. || Fractions and decimal numbers can represent the same number. | Decimals can be expressed as fractions with a denominator that is equivalent to the place value of the last non-zero digit of the decimal number.","understanding":"There are infinitely many equivalent fractions that represent the same number. | Exactly one of infinitely many equivalent fractions is in simplest form. || Decimal numbers that terminate (do not repeat) are fractions with denominators of 10, 100, etc. | Fractions and decimal numbers that represent the same number are associated with the same point on the number line.","skills_procedures":"Model equivalent fractions by partitioning a whole in multiple ways. | Determine fractions equivalent to a given fraction. | Relate the position of equivalent fractions on the number line. | Identify fractions in which the numerator and denominator have a common factor. | Simplify a given fraction by dividing the numerator and denominator by a common factor. | Express a fraction in simplest form. | Compare and order fractions. || Relate fractions and equivalent decimal numbers to their positions on the number line. | Express fractions as decimal numbers and vice versa, limited to denominators that are 10 or 100.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 4, $txt$AB-G4-NUM-6$txt$, $txt$derived$txt$, $txt$0zWkCgBoa02WpE4F9KEh7Q$txt$, $txt$outcome$txt$, null, $txt$Students interpret percentages.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can percentages standardize part-whole relationships?","knowledge":"Percentage is represented symbolically with \\% . | Decimals can be expressed as percentages by multiplying by 100. | Percentages can be expressed as decimals by dividing by 100. | One percent represents one hundredth of a whole.","understanding":"Fractions, decimals, and percentages can represent the same part-whole relationship.","skills_procedures":"Investigate percentage in familiar situations. | Compare percentages within 100 \\% . | Express the fraction, decimal, and percentage representations of the same part-whole relationship.","source_last_modified":"2025-05-30","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$ALG$txt$), 4, $txt$AB-G4-ALG-1$txt$, $txt$derived$txt$, $txt$MAT4-OI2-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students represent and apply equality in multiple ways.$txt$, $txt${"organizing_idea":"Algebra: Equations express relationships between quantities.","guiding_question":"How can equality create opportunities to reimagine number?","knowledge":"An expression can have multiple operations. | The conventional order of operations provides a set of rules for evaluating expressions, including the following: | Multiplication and division are performed before addition and subtraction. | Multiplication and division are performed in order from left to right. | Addition and subtraction are performed in order from left to right. || Equations can be solved through a process of adding, subtracting, multiplying, or dividing the same number on both sides of the equation (preservation of equality).","understanding":"There are infinitely many expressions that represent the same number. | The order in which operations are performed can affect the value of an expression. || An equation is solved by determining an unknown value that makes the left and right sides of the equation equal.","skills_procedures":"Evaluate expressions according to the order of operations. | Create various expressions of the same number, using one or more operations. || Write equations involving one operation to represent a situation. | Investigate preservation of equality, using a balance model. | Investigate preservation of equality, using an equation without an unknown value. | Apply preservation of equality to determine the unknown value in an equation, limited to equations with one operation. | Solve problems, using equations, limited to equations with one operation.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$GEO$txt$), 4, $txt$AB-G4-GEO-1$txt$, $txt$derived$txt$, $txt$MAT4-OI3-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze and explain geometric properties.$txt$, $txt${"organizing_idea":"Geometry: Shapes are defined and related by geometric attributes.","guiding_question":"In what ways can geometric properties define space?","knowledge":"Angle relationships, including supplementary and complementary, are geometric properties. | Two angles that compose 90° are complementary angles. | Two angles that compose 180° are supplementary angles. | Quadrilaterals include | squares | rectangles | parallelograms | trapezoids | rhombuses | Side length can be used to describe triangles as | equilateral | isosceles | scalene | Triangles can be classified according to angle as | right | obtuse | acute || Many shapes in the environment resemble polygons. | Transformations can be used to illustrate geometric properties of a polygon.","understanding":"Geometric properties are measurable. | Geometric properties define a hierarchy for classifying shapes. || A shape resembling a polygon that does not share the defining geometric properties of the polygon is a close approximation.","skills_procedures":"Identify relationships between the sides of a polygon, including parallel, equal length, or perpendicular, by measuring. | Identify relationships between angles at vertices of a polygon, including equal, supplementary, and complementary, by measuring. | Identify relationships between the faces of three-dimensional models of prisms, including parallel or perpendicular, by measuring. | Describe triangles according to side length. | Classify triangles as right, acute, or obtuse, using geometric properties related to angles. | Classify quadrilaterals in a hierarchy according to geometric properties. || Show, using geometric properties, that a close approximation of a polygon is not the same as the polygon. | Verify geometric properties of polygons by translating, rotating, or reflecting, using hands-on materials or digital applications.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$MEA$txt$), 4, $txt$AB-G4-MEA-1$txt$, $txt$derived$txt$, $txt$MAT4-OI5-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students interpret and express area.$txt$, $txt${"organizing_idea":"Measurement: Attributes such as length, area, volume, and angle are quantified by measurement.","guiding_question":"How can area characterize space?","knowledge":"Tiling is the process of measuring an area with many copies of a unit, without gaps or overlaps. | The unit can be chosen based on the area to be measured. | Area can be measured with non-standard units or standard units. | The area of a rectangle equals the product of its perpendicular side lengths. || Area can be estimated by using a referent for a square centimetre.","understanding":"Area is a measurable attribute that describes the amount of two-dimensional space contained within a region. | Area may be interpreted as the result of motion of a length. | An area remains the same when decomposed or rearranged. | Area is measured with equal-sized units that themselves have area and do not need to resemble the region being measured. | The area of a rectangle can be perceived as square-shaped units structured in a two-dimensional array. || Area can be estimated when less accuracy is required.","skills_procedures":"Model area by dragging a length, using hands-on materials or digital applications. | Recognize the rearrangement of area in First Nations, Métis, or Inuit design. | Compare non-standard units that tile to non-standard units that do not tile. | Measure area with non-standard units by tiling. | Measure area with standard units by tiling with square centimetres. | Visualize and model the area of various rectangles as two-dimensional arrays of square shaped units. | Determine the area of a rectangle, using multiplication. | Solve problems involving area of rectangles. || Identify referents for a square centimetre. | Estimate an area by visualizing the iteration of a referent for a square centimetre. | Estimate an area by rearranging or combining partial units.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$MEA$txt$), 4, $txt$AB-G4-MEA-2$txt$, $txt$derived$txt$, $txt$MAT4-OI5-GQ2-LO1$txt$, $txt$outcome$txt$, null, $txt$Students determine and express angles, using standard units.$txt$, $txt${"organizing_idea":"Measurement: Attributes such as length, area, volume, and angle are quantified by measurement.","guiding_question":"In what ways can angles be described?","knowledge":"One degree represents \\frac{1}{360} of the rotation of a full circle. | Angles can be classified according to their measure: | Acute angles measure less than 90°. | Right angles measure 90°. | Obtuse angles measure between 90° and 180°. | Straight angles measure 180°. | A benchmark is a known angle to which another angle can be compared.","understanding":"Angles are quantified by measurement and based on the division of a circle. | An angle is measured with equal-sized units that themselves are angles.","skills_procedures":"Measure an angle with degrees, using a protractor. | Describe an angle as acute, right, obtuse, or straight. | Relate angles of 90°, 180°, 270°, and 360° to fractions of a circle. | Estimate angles by comparing to benchmarks of 45°, 90°, 180°, 270°, and 360°.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$PAT$txt$), 4, $txt$AB-G4-PAT-1$txt$, $txt$derived$txt$, $txt$MAT4-OI6-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students interpret and explain arithmetic and geometric sequences.$txt$, $txt${"organizing_idea":"Patterns: Awareness of patterns supports problem solving in various situations.","guiding_question":"How can sequences provide insight into change?","knowledge":"The sequences of triangular and square numbers are examples of increasing sequences. | The Fibonacci sequence is an increasing sequence that occurs in nature. || An arithmetic sequence progresses through addition or subtraction. | A skip-counting sequence is an example of an arithmetic sequence. | A geometric sequence progresses through multiplication. | A geometric sequence begins at a number other than zero.","understanding":"Sequences may increase or decrease. | Different representations can provide new perspectives of the increase or decrease of a sequence. || An arithmetic sequence has a constant difference between consecutive terms. | A geometric sequence has a constant multiplicative change between consecutive terms.","skills_procedures":"Investigate increasing sequences, including the Fibonacci sequence, in multiple representations. | Create and explain increasing or decreasing sequences, including numerical sequences. | Express a numerical sequence to represent a concrete or pictorial sequence. || Recognize arithmetic and geometric sequences. | Describe the initial term and the constant change in an arithmetic sequence. | Express the first five terms of an arithmetic sequence related to a given initial term and constant change. | Describe the initial term and the constant change in a geometric sequence. | Express the first five terms of a geometric sequence related to a given initial term and constant change.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$TIM$txt$), 4, $txt$AB-G4-TIM-1$txt$, $txt$derived$txt$, $txt$MAT4-OI7-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students communicate duration with standard units of time.$txt$, $txt${"organizing_idea":"Time: Duration is described and quantified by time.","guiding_question":"What might be the relevance of duration to daily living?","knowledge":"Time of day can be expressed with fractions of a circle, including | quarter past the hour | half past the hour | quarter to the hour | Duration can be determined by finding the difference between a start time and an end time.","understanding":"Analog clocks can relate duration to a circle.","skills_procedures":"Relate durations of 15 minutes, 20 minutes, 30 minutes, 40 minutes, and 45 minutes to fractions of a circle. | Express time of day, using fractions. | Determine duration in minutes, using a clock. | Apply addition and subtraction strategies to the calculation of duration. | Convert between hours, minutes, and seconds. | Compare the duration of events, using standard units. | Solve problems involving duration.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$STA$txt$), 4, $txt$AB-G4-STA-1$txt$, $txt$derived$txt$, $txt$MAT4-OI8-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students evaluate the use of scale in graphical representations of data.$txt$, $txt${"organizing_idea":"Statistics: The science of collecting, analyzing, visualizing, and interpreting data can inform understanding and decision making.","guiding_question":"In what ways can communication be shaped by the choice of representation?","knowledge":"A statistical problem-solving process includes | formulating statistical questions | collecting data | representing data | interpreting data || Many-to-one correspondence is the representation of many objects by using one object or interval on a graph. | Common graphs include | pictographs | bar graphs | dot plots","understanding":"Representation is part of a statistical problem-solving process. || Representation can express many-to-one correspondence by defining a scale. | Different representations tell different stories about the same data.","skills_procedures":"Engage in a statistical problem-solving process. || Select an appropriate scale to represent data. | Represent data in a graph, using many-to-one correspondence. | Describe the effect of scale on representation. | Justify the choice of graph used to represent certain data. | Compare different graphs of the same data. | Interpret data represented in various graphs.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat4$txt$, 13, false, $txt$2026-10-17$txt$::date);
insert into public.standard (doc_id, strand_id, grade, code, code_type, source_system_id, level, parent_id, text, extra, source_url, display_order, needs_review, last_verified)
values
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 5, $txt$AB-G5-NUM-1$txt$, $txt$derived$txt$, $txt$MAT5-OI1-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze patterns in place value.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can the infinite nature of place value enhance insight into number?","knowledge":"A number expressed with more decimal places is more precise. | A zero in the rightmost place of a decimal number does not change the value of the number. | There are infinitely many decimal numbers between any two decimal numbers.","understanding":"Place value symmetry extends infinitely to the left and right of the ones place.","skills_procedures":"Relate the names of place values that are the same number of places to the left and right of the ones place. | Express numbers within 10 000 000, including decimal numbers to thousandths, using words and numerals. | Relate a decimal number to its position on the number line. | Determine a decimal number between any two other decimal numbers. | Compare and order numbers, including decimal numbers. | Express the relationship between two numbers, including decimal numbers, using < , > , or = . | Round numbers, including decimal numbers, to various places according to context.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 5, $txt$AB-G5-NUM-2$txt$, $txt$derived$txt$, $txt$MAT5-OI1-GQ2-LO1$txt$, $txt$outcome$txt$, null, $txt$Students add and subtract within 1 000 000, including decimal numbers to thousandths, using standard algorithms.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"In what ways can the processes of addition and subtraction be articulated?","knowledge":"Standard algorithms are efficient procedures for addition and subtraction.","understanding":"Addition and subtraction of numbers with many digits is facilitated by standard algorithms.","skills_procedures":"Add and subtract numbers, including decimal numbers, using standard algorithms. | Assess the reasonableness of a sum or difference, using estimation. | Solve problems, using addition and subtraction, including problems involving money.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 5, $txt$AB-G5-NUM-3$txt$, $txt$derived$txt$, $txt$MAT5-OI1-GQ3-LO1$txt$, $txt$outcome$txt$, null, $txt$Students determine divisibility of natural numbers.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"In what ways can divisibility characterize natural numbers?","knowledge":"A divisibility test can be used to determine factors of a natural number. | Division by zero is not possible.","understanding":"A number is divisible by another number if it can be divided with a remainder of 0.","skills_procedures":"Investigate divisibility by natural numbers from 0 to 10. | Generalize divisibility tests for 2, 3, and 5. | Determine factors of natural numbers, using divisibility tests.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 5, $txt$AB-G5-NUM-4$txt$, $txt$derived$txt$, $txt$MAT5-OI1-GQ4-LO1$txt$, $txt$outcome$txt$, null, $txt$Students multiply and divide natural numbers within 100 000, including with standard algorithms.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"In what ways can the processes of multiplication and division be articulated?","knowledge":"Multiplication and division of numbers with many digits is facilitated by standard algorithms.","understanding":"Standard algorithms are efficient procedures for multiplication and division.","skills_procedures":"Explain the standard algorithms for multiplication and division of natural numbers. | Multiply up to 3-digit by 2-digit natural numbers, using standard algorithms. | Divide 3-digit by 1-digit natural numbers, using standard algorithms. | Express a quotient with or without a remainder according to context. | Assess the reasonableness of a product or quotient, using estimation. | Solve problems, using multiplication and division of natural numbers.","source_last_modified":"2025-05-30","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 5, $txt$AB-G5-NUM-5$txt$, $txt$derived$txt$, $txt$MAT5-OI1-GQ5-LO1$txt$, $txt$outcome$txt$, null, $txt$Students interpret improper fractions.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"In what ways can fractions communicate numbers greater than one?","knowledge":"A fraction can represent quantities greater than one. | An improper fraction has a numerator that is greater than its denominator. | Natural numbers can be expressed as improper fractions with a denominator of 1. | A mixed number of the form A\\frac{b}{c} , composed of a number of wholes, A , and a fractional part, \\frac{b}{c} , can represent an improper fraction.","understanding":"Fractions allow counting and measuring between whole quantities. | Improper fractions and mixed numbers that represent the same number are associated with the same point on the number line.","skills_procedures":"Relate fractions, improper fractions, and mixed numbers to their positions on the number line. | Count beyond 1, using fractions with the same denominator. | Model fractions, including improper fractions and mixed numbers, using quantities, lengths, and areas. | Express improper fractions and mixed numbers symbolically. | Express an improper fraction as a mixed number and vice versa. | Compare fractions, including improper fractions and mixed numbers, to benchmarks of 0, \\frac{1}{2} , and 1.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 5, $txt$AB-G5-NUM-6$txt$, $txt$derived$txt$, $txt$h9k9LsDzCEGrqR92bPiBog$txt$, $txt$outcome$txt$, null, $txt$Students add and subtract fractions with common denominators.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can the composition of fractions facilitate operating with fractions?","knowledge":"Fractions with common denominators can be composed or decomposed to model the change in a quantity of unit fractions. | Addition and subtraction of fractions with common denominators does not change the unit fraction from which they are composed. | Fractions greater than one can be added or subtracted as mixed numbers or improper fractions.","understanding":"Fractions with common denominators are multiples of the same unit fraction. | Properties for addition and subtraction of natural numbers apply to fractions.","skills_procedures":"Investigate the composition and decomposition of a quantity within 1, using unit fractions. | Express the composition or decomposition of fractions with common denominators as a sum or difference. | Compare strategies for adding or subtracting improper fractions to strategies for adding or subtracting mixed numbers. | Add and subtract fractions with common denominators within 100, including improper fractions and mixed numbers. | Solve problems requiring addition and subtraction of fractions with common denominators, including improper fractions and mixed numbers.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 5, $txt$AB-G5-NUM-7$txt$, $txt$derived$txt$, $txt$_tTreLA_0Ey9KlNK1XSxIA$txt$, $txt$outcome$txt$, null, $txt$Students employ ratios to represent relationships between quantities.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can ratios provide new ways to relate numbers?","knowledge":"A ratio can express part-part or part-whole relationships between two countable or measurable quantities. | A ratio can be expressed with a fraction or with a colon. | A percentage represents a part-whole ratio that compares a quantity to 100.","understanding":"A ratio is a comparison of two quantities in a specific situation. | Fractions, decimals, ratios, and percentages can represent the same part-whole relationship.","skills_procedures":"Express part-part ratios and part-whole ratios of the same whole to describe various situations. | Express, symbolically, the same part-whole relationship as a ratio, fraction, decimal, and percentage.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$ALG$txt$), 5, $txt$AB-G5-ALG-1$txt$, $txt$derived$txt$, $txt$MAT5-OI2-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students interpret numerical and algebraic expressions.$txt$, $txt${"organizing_idea":"Algebra: Equations express relationships between quantities.","guiding_question":"How can expressions enhance communication of number?","knowledge":"Numerical expressions with multiple operations may include parentheses to group numbers and operations. | The conventional order of operations includes performing operations in parentheses before other operations. || Expressions that include variables are called algebraic expressions. | A variable can be interpreted as a specific unknown value and is represented symbolically with a letter. | Products with variables are expressed without the multiplication sign. | Quotients with variables are expressed by using fraction notation. | An algebraic term is the product of a number, called a coefficient, and a variable. | A constant term is a number. | A variable can be replaced by a given number in order to evaluate an expression. || The process of applying inverse operations can be used to solve an equation. | The value of the variable obtained by solving an equation is the solution.","understanding":"Numerical expressions represent a quantity of known value. | Parentheses change the order of operations in a numerical expression. || Algebraic expressions use variables to represent quantities of unknown value. | Algebraic expressions may be composed of one algebraic term or the sum of algebraic and constant terms. || Equality is preserved by applying inverse operations to algebraic expressions on each side of an equation. | The expressions on each side of an equation will be equal when evaluated by using the correct solution.","skills_procedures":"Evaluate numerical expressions involving addition or subtraction in parentheses according to the order of operations. || Relate repeated addition of a variable to the product of a number and a variable. | Express the product of a number and a variable, using a coefficient. | Express the quotient of a variable and a number as a fraction. | Recognize a product with a variable, a quotient with a variable, or a number as a single term. | Write an algebraic expression involving one or two terms to describe an unknown value. | Evaluate an algebraic expression by substituting a given number for the variable. || Write equations involving one or two operations to represent a situation. | Investigate order of operations when performing inverse operations on both sides of an equation. | Apply inverse operations to solve an equation, limited to equations with one or two operations. | Verify the solution to an equation by evaluating expressions on each side of the equation. | Solve problems, using equations, limited to equations with one or two operations.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$GEO$txt$), 5, $txt$AB-G5-GEO-1$txt$, $txt$derived$txt$, $txt$MAT5-OI3-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students investigate symmetry as a geometric property.$txt$, $txt${"organizing_idea":"Geometry: Shapes are defined and related by geometric attributes.","guiding_question":"In what ways might symmetry characterize shape?","knowledge":"A 2-D shape has reflection symmetry if there is a straight line over which the shape reflects and the two halves exactly match. | A 3-D shape has reflection symmetry if there is a plane over which the shape reflects and the two halves exactly match. | A 2-D shape has rotation symmetry if it exactly overlaps itself one or more times within a rotation of less than 360° around its centre point. | Order of rotation symmetry describes the number of times a shape coincides with itself within a rotation of 360° around its centre point. | Central symmetry is the rotational symmetry by 180°. | The straight line that connects a point with its image in the central symmetry passes through the centre of rotation. | Symmetry can be found in First Nations, Métis, and Inuit designs, such as | basket weaving | wampum belts | quilts | First Nations beadwork, Inuit beadwork, or Métis floral beadwork | architecture such as tipis or longhouses || In a regular polygon, the number of sides equals the number of reflection symmetries and the number of rotation symmetries. | A circle has infinitely many reflection and rotation symmetries.","understanding":"Symmetry is a property of shapes. | Symmetry can be created and can occur in nature. || Symmetry is related to other geometric properties.","skills_procedures":"Recognize symmetry in nature. | Recognize symmetry in First Nations, Métis, and Inuit designs. | Investigate symmetry in familiar 2-D and 3-D shapes, using hands-on materials or digital applications. | Show the line of symmetry of a 2-D shape. | Describe the order of rotation symmetry of a 2-D shape. || Compare the number of reflection and rotation symmetries of a 2-D shape to the number of equal sides and angles. | Classify 2-D shapes according to the number of reflection or rotation symmetries.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$CG$txt$), 5, $txt$AB-G5-COO-1$txt$, $txt$derived$txt$, $txt$MAT5-OI4-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students relate location to position on a grid.$txt$, $txt${"organizing_idea":"Coordinate Geometry: Location and movement of objects in space can be communicated by using a coordinate grid.","guiding_question":"How can location enhance the ways in which space is defined?","knowledge":"Coordinate grids use coordinates to indicate the location of the point where the vertical and horizontal grid lines intersect. | Coordinates are ordered pairs of numbers in which the first number indicates the distance from the vertical axis and the second number indicates the distance from the horizontal axis. | Positional language includes | left | right | up | down","understanding":"Location can describe the position of shapes in space. | Location can be described precisely by using a coordinate grid.","skills_procedures":"Locate a point on a coordinate grid, given the coordinates of the point. | Describe the location of a point on a coordinate grid, using coordinates. | Describe the location of a point on a coordinate grid in relation to the location of another point, using positional language. | Model a polygon on a coordinate grid, using coordinates to indicate the vertices. | Describe the location of the vertices of a polygon on a coordinate grid, using coordinates.","source_last_modified":"2025-05-30","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$MEA$txt$), 5, $txt$AB-G5-MEA-1$txt$, $txt$derived$txt$, $txt$MAT5-OI5-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students estimate and calculate area, using standard units.$txt$, $txt${"organizing_idea":"Measurement: Attributes such as length, area, volume, and angle are quantified by measurement.","guiding_question":"In what ways can area be communicated?","knowledge":"Area is expressed in the following standard units, derived from standard units of length: | square centimetres | square metres | square kilometres | A square centimetre (cm 2 ) is an area equivalent to the area of a square measuring 1 centimetre by 1 centimetre. | A square metre (m 2 ) is an area equivalent to the area of a square measuring 1 metre by 1 metre. | A square kilometre (km 2 ) is an area equivalent to the area of a square measuring 1 kilometre by 1 kilometre. | Among all rectangles with the same area, the square has the least perimeter.","understanding":"Area can be expressed in various units according to context and desired precision. | Rectangles with the same area can have different perimeters.","skills_procedures":"Relate a centimetre to a square centimetre. | Relate a metre to a square metre. | Relate a square centimetre to a square metre. | Express the relationship between square centimetres, square metres, and square kilometres. | Justify the choice of square centimetres, square metres, or square kilometres as appropriate units to express various areas. | Estimate an area by comparing to a benchmark of a square centimetre or square metre. | Express the area of a rectangle, using standard units, given the lengths of its sides. | Compare the perimeters of various rectangles with the same area. | Describe the rectangle with the least perimeter for a given area. | Solve problems involving perimeter and area of rectangles.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$PAT$txt$), 5, $txt$AB-G5-PAT-1$txt$, $txt$derived$txt$, $txt$MAT5-OI6-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students relate terms to position within an arithmetic sequence.$txt$, $txt${"organizing_idea":"Patterns: Awareness of patterns supports problem solving in various situations.","guiding_question":"How might representation of a sequence provide insight into change?","knowledge":"A table of values representing an arithmetic sequence lists the position in the first column or row and the corresponding term in the second column or row. | Points representing an arithmetic sequence on a coordinate grid fit on a straight line. | An algebraic expression can describe the relationship between the positions and terms of an arithmetic sequence.","understanding":"Each term of an arithmetic sequence corresponds to a natural number indicating position in the sequence.","skills_procedures":"Represent one-to-one correspondence between positions and terms of an arithmetic sequence in a table of values and on a coordinate grid. | Describe the graph of an arithmetic sequence as a straight line. | Describe a rule, limited to one operation, that expresses correspondence between positions and terms of an arithmetic sequence. | Write an algebraic expression, limited to one operation, that represents correspondence between positions and terms of an arithmetic sequence. | Determine the missing term in an arithmetic sequence that corresponds to a given position. | Solve problems involving an arithmetic sequence.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$STA$txt$), 5, $txt$AB-G5-STA-1$txt$, $txt$derived$txt$, $txt$MAT5-OI8-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze frequency in categorical data.$txt$, $txt${"organizing_idea":"Statistics: The science of collecting, analyzing, visualizing, and interpreting data can inform understanding and decision making.","guiding_question":"How might frequency bring meaning to data?","knowledge":"Frequency can be compared across categories to answer statistical questions. | The mode is the category with the highest frequency. || Data can be collected by asking closed-list and open-ended questions. | Closed-list questions provide a list of possible responses to choose from. | Open-ended questions allow any response. | Responses can be categorized in various ways. | Representations of frequency include | bar graphs | dot plots | stem-and-leaf plots","understanding":"Frequency is a count of categorized data, but it is not the data value itself. || Frequency can be a count of categorized responses to a question. | Frequency can be used to summarize data. | Frequency can be represented in various forms.","skills_procedures":"Examine categorized data in tables and graphs. | Determine frequency for each category of a set of data by counting individual data points. | Identify the mode in various representations of data. | Recognize data sets with no mode, one mode, or multiple modes. | Justify possible answers to a statistical question, using mode. || Discuss potential categories for open-ended questions and closed-list questions in relation to the same statistical question. | Formulate closed-list questions to collect data to answer a statistical question. | Categorize data that was collected by using a closed-list question. | Organize counts of categorized data in a frequency table. | Create various representations of data, including with technology, to interpret frequency.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat5$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 6, $txt$AB-G6-NUM-1$txt$, $txt$derived$txt$, $txt$MAT6-OI1-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students investigate magnitude with positive and negative numbers.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can the infinite nature of the number line broaden the perception of number?","knowledge":"Negative numbers are to the left of zero on the number line visualized horizontally, and below zero on the number line visualized vertically. | Positive numbers can be represented symbolically with or without a positive sign (+). | Negative numbers are represented symbolically with a negative sign (−). | Zero is neither positive nor negative. | Negative numbers communicate meaning in context, including | temperature | debt | elevation | Magnitude is a number of units counted or measured from zero on the number line. | Every positive number has an opposite negative number with the same magnitude. | A number and its opposite are called additive inverses. || The set of integers includes all natural numbers and their additive inverses. | The sum of any number and its additive inverse is zero. | The sum of two positive numbers is a positive number. | The sum of two negative numbers is a negative number. | The sum of a positive number and a negative number can be interpreted as the sum of zero and another number. || Subtracting a number is the same as adding its additive inverse.","understanding":"Symmetry of the number line extends infinitely to the left and right of zero or above and below zero. | Direction relative to zero is indicated symbolically with a positive or negative sign. | Magnitude with direction distinguishes between positive and negative numbers. || Any number can be expressed as a sum in infinitely many ways. || The difference of any two numbers can be interpreted as a sum.","skills_procedures":"Identify negative numbers in familiar contexts, including contexts that use vertical or horizontal models of the number line. | Express positive and negative numbers symbolically, in context. | Relate magnitude to the distance from zero on the number line. | Relate positive and negative numbers, including additive inverses, to their positions on horizontal and vertical models of the number line. | Compare and order positive and negative numbers. | Express the relationship between two numbers, including positive and negative numbers, using < , > , or = . || Investigate addition of an integer and its additive inverse. | Express zero as the sum of integers in multiple ways. | Model the sum of two positive integers. | Model the sum of two negative integers. | Model the sum of a positive and negative integer as the sum of zero and another integer. || Express a difference as a sum.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 6, $txt$AB-G6-NUM-2$txt$, $txt$derived$txt$, $txt$MAT6-OI1-GQ2-LO1$txt$, $txt$outcome$txt$, null, $txt$Students solve problems, using standard algorithms for addition and subtraction.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can the processes of addition and subtraction be applied to problem solving?","knowledge":"Standard algorithms are reliable procedures for addition and subtraction. | Contexts for problems involving addition and subtraction include money and metric measurement.","understanding":"Addition and subtraction of numbers in problem-solving contexts is facilitated by standard algorithms.","skills_procedures":"Solve problems in various contexts, using standard algorithms for addition and subtraction.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 6, $txt$AB-G6-NUM-3$txt$, $txt$derived$txt$, $txt$MAT6-OI1-GQ3-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze numbers, using prime factorization and exponentiation.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can prime factorization and exponentiation provide new perspectives of numbers?","knowledge":"The order in which three or more numbers are multiplied does not affect the product (associative property). | Any composite number can be factored and expressed as a product of smaller numbers. | Prime factorization represents a number as a product of prime numbers. | Any composite factor of a number can be determined from its prime factors. || Repeated multiplication of identical factors can be represented symbolically as a power (exponentiation). | A power, A^n , includes a base, A , representing the repeated factor, and an exponent, n , indicating the number of repeated factors. | Any repeated prime factor within a prime factorization can be expressed as a power.","understanding":"A product can be composed in multiple ways. | The prime factors of a number provide a picture of its divisibility. || Different representations of a product can provide new perspectives of its divisibility. | A power is divisible by its base.","skills_procedures":"Compose a product in multiple ways, including with more than two factors. | Express the prime factorization of a composite number. | Determine common factors for two natural numbers, using prime factorization. | Determine divisibility of a natural number from its prime factorization. || Identify the base and exponent in a power. | Express the product of identical factors as a power, including within a prime factorization. | Describe the divisibility of numbers represented in various forms.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 6, $txt$AB-G6-NUM-4$txt$, $txt$derived$txt$, $txt$MAT6-OI1-GQ4-LO1$txt$, $txt$outcome$txt$, null, $txt$Students apply standard algorithms to multiplication and division of decimal and natural numbers.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can the processes of multiplication and division be applied to decimal numbers?","knowledge":"Standard algorithms are reliable procedures for multiplication and division of numbers, including decimal numbers. | A quotient with a remainder can be expressed as a decimal number.","understanding":"Multiplication and division of decimal numbers is facilitated by standard algorithms.","skills_procedures":"Explain the standard algorithms for multiplication and division of decimal numbers. | Multiply and divide up to 3-digit natural or decimal numbers by 2-digit natural numbers, using standard algorithms. | Assess the reasonableness of a product or quotient, using estimation. | Solve problems, using multiplication and division, including problems involving money.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 6, $txt$AB-G6-NUM-5$txt$, $txt$derived$txt$, $txt$MAT6-OI1-GQ5-LO1$txt$, $txt$outcome$txt$, null, $txt$Students relate fractions to quotients.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can equal sharing contribute meaning to fractions?","knowledge":"An equal-sharing situation can be represented by a fraction in which the numerator represents the quantity to be shared and the denominator represents the number of shares. | Division can be used to determine an equal share. | Division of the numerator by the denominator of a fraction provides the equivalent decimal number.","understanding":"Fractions represent quotients in equal-sharing situations. | All equivalent fractions represent the same quotient.","skills_procedures":"Model an equal-sharing situation in more than one way. | Describe an equal-sharing situation, using a fraction. | Express a fraction as a division statement and vice versa. | Convert a quotient from fraction to decimal form, using division.","source_last_modified":"2025-05-30","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 6, $txt$AB-G6-NUM-6$txt$, $txt$derived$txt$, $txt$eVwjDHYcXUuWmBMwi-XVjg$txt$, $txt$outcome$txt$, null, $txt$Students add and subtract fractions with denominators within 100.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can the addition and subtraction of fractions be generalized?","knowledge":"Addition and subtraction of fractions is facilitated by representing the fractions with common denominators. | Denominators are related if one is a multiple of the other. | Multiplication of one denominator by the factor that relates it to another denominator achieves common denominators. | The product of the denominators of two fractions provides a common denominator.","understanding":"Fractions with common denominators have the same units. | Any numbers with the same unit can be compared, added, or subtracted.","skills_procedures":"Recognize two fractions with related denominators. | Determine the factor that relates one denominator to another. | Express two fractions with common denominators. | Add and subtract fractions. | Solve problems involving addition and subtraction of fractions.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 6, $txt$AB-G6-NUM-7$txt$, $txt$derived$txt$, $txt$sAJrul14WkyWyL8gNRW3rw$txt$, $txt$outcome$txt$, null, $txt$Students interpret the multiplication of natural numbers by fractions.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"How can an understanding of multiplication be extended to fractions?","knowledge":"Multiplication of a natural number by a fraction is equivalent to multiplication by the fraction’s numerator and division by its denominator. | \\enspace \\enspace \\enspace \\enspace \\enspace a \\times \\dfrac{b}{c} = \\dfrac{ab}{c} | Multiplication by a unit fraction is equivalent to division by its denominator. | \\enspace \\enspace \\enspace \\enspace \\enspace a \\times \\dfrac{1}{b} = \\dfrac{a}{b} | The product of a fraction and a natural number is the fraction with | a numerator that is the product of the numerator of the given fraction and the natural number | a denominator that is the denominator of the given fraction | \\enspace \\enspace \\enspace \\enspace \\enspace \\dfrac{a}{b} \\times c = \\dfrac{ac}{b}","understanding":"Multiplication does not always result in a larger number. | Multiplication of a natural number by a fraction can be interpreted as repeated addition of the fraction. | Multiplication of a fraction by a natural number can be interpreted as taking part of a quantity.","skills_procedures":"Relate multiplication of a natural number by a fraction to repeated addition of the fraction. | Multiply a natural number by a fraction. | Relate multiplication by a unit fraction to division. | Multiply a natural number by a unit fraction. | Model a fraction of a natural number. | Multiply a fraction by a natural number. | Solve problems, using multiplication of a fraction and a natural number.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$NUM$txt$), 6, $txt$AB-G6-NUM-8$txt$, $txt$derived$txt$, $txt$a0drDciYDkWmZ8qt5-1K0A$txt$, $txt$outcome$txt$, null, $txt$Students apply equivalence to the interpretation of ratios and rates.$txt$, $txt${"organizing_idea":"Number: Quantity is measured with numbers that enable counting, labelling, comparing, and operating.","guiding_question":"In what ways can equivalent ratios support proportional reasoning?","knowledge":"A proportional relationship exists when one quantity is a multiple of the other. | Equivalent ratios can be created by multiplying or dividing both terms of a given ratio by the same number. | A proportion is an expression of equivalence between two ratios. | A rate describes the proportional relationship represented by a set of equivalent ratios. | A unit rate expresses a proportional relationship as a rate with a second term of 1. | A percentage describes a proportional relationship between a quantity and 100. | Percent of a number can be determined by multiplying the number by the percent and dividing by 100.","understanding":"All equivalent ratios express the same proportional relationship. | A rate can be used to extend a given proportional relationship to different quantities.","skills_procedures":"Determine whether two ratios are equivalent. | Determine an equivalent ratio, using a proportion. | Express a unit rate to represent a given rate, including unit price and speed. | Relate percentage of a number to a proportion. | Determine a percent of a number, limited to percentages within 100 \\% . | Solve problems involving ratios, rates, and proportions.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$ALG$txt$), 6, $txt$AB-G6-ALG-1$txt$, $txt$derived$txt$, $txt$MAT6-OI2-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze expressions and solve algebraic equations.$txt$, $txt${"organizing_idea":"Algebra: Equations express relationships between quantities.","guiding_question":"How can expressions support a generalized interpretation of number?","knowledge":"Powers can appear in numerical expressions. | The conventional order of operations includes performing operations in parentheses, followed by evaluating powers before other operations. || Algebraic terms with exactly the same variable are like terms. | Constant terms are like terms. | Like terms can be combined through addition or subtraction. | The terms of an algebraic expression can be rearranged according to algebraic properties. | Algebraic properties include | commutative property of addition: a + b = b + a | commutative property of multiplication: ab = ba | associative property of addition: (a + b) + c = a + (b + c) | associative property of multiplication: a(bc) = b(ac) | distributive property: a(b + c) = ab + ac || All simplified forms of a linear equation have the same solution.","understanding":"The conventional order of operations can be applied to simplify or evaluate expressions. || Algebraic properties ensure equivalence of algebraic expressions. || Algebraic expressions on each side of an equation can be simplified into equivalent expressions to facilitate equation solving.","skills_procedures":"Evaluate numerical expressions involving operations in parentheses and powers according to the order of operations. || Investigate like terms by modelling an algebraic expression. | Simplify algebraic expressions by combining like terms. | Express the terms of an algebraic expression in a different order in accordance with algebraic properties. || Simplify algebraic expressions on both sides of an equation. | Solve equations, limited to equations with one or two operations. | Determine different strategies for solving equations. | Verify the solution to an equation by evaluating expressions on each side of the equation. | Solve problems, using equations, limited to equations with one or two operations.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$GEO$txt$), 6, $txt$AB-G6-GEO-1$txt$, $txt$derived$txt$, $txt$MAT6-OI3-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze shapes through symmetry and congruence.$txt$, $txt${"organizing_idea":"Geometry: Shapes are defined and related by geometric attributes.","guiding_question":"How can congruence support interpretation of symmetry?","knowledge":"Symmetrical shapes can be mapped by any combination of reflections and rotations. | A tessellation is the tiling of a plane with symmetrical shapes. | Tessellations are evident in First Nations and Métis star blanket designs that convey a specific purpose. || Shapes related by symmetry are congruent to each other. | Congruent shapes may not be related by symmetry.","understanding":"Symmetry is a relationship between two shapes that can be mapped exactly onto each other through reflection or rotation. || Congruence is a relationship between two shapes of identical size and shape. | Congruence is not dependent on orientation or location of the shapes.","skills_procedures":"Verify symmetry of two shapes by reflecting or rotating one shape onto another. | Describe the symmetry between two shapes as reflection symmetry or rotation symmetry. | Visualize and describe a combination of two transformations that relate symmetrical shapes. | Describe the symmetry modelled in a tessellation. | Investigate tessellations found in objects, art, or architecture. || Demonstrate congruence between two shapes in any orientation by superimposing, using hands-on materials or digital applications. | Describe symmetrical shapes as congruent.","source_last_modified":"2026-06-29","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$CG$txt$), 6, $txt$AB-G6-COO-1$txt$, $txt$derived$txt$, $txt$MAT6-OI4-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students explain location and movement in relation to position in the Cartesian plane.$txt$, $txt${"organizing_idea":"Coordinate Geometry: Location and movement of objects in space can be communicated by using a coordinate grid.","guiding_question":"In what ways can location be communicated?","knowledge":"The Cartesian plane is named after French mathematician René Descartes. | The Cartesian plane uses coordinates, (x, y) , to indicate the location of the point where the vertical line passing through (x, 0) and the horizontal line passing through (0, y) intersect. | The x -axis consists of those points whose y -coordinate is zero, and the y -axis consists of those points whose x -coordinate is zero. | The x -axis and the y -axis intersect at the origin, (0, 0) . | An ordered pair is represented symbolically as (x, y) . | An ordered pair indicates the horizontal distance from the y -axis with the x -coordinate and the vertical distance from the x -axis with the y -coordinate. || A translation describes a combination of horizontal and vertical movements as a single movement. | A reflection describes movement across a line of reflection. | A rotation describes an amount of movement around a centre of rotation along a circular path in either a clockwise or counter-clockwise direction.","understanding":"Location can be described by using the Cartesian plane. | The Cartesian plane is the two-dimensional equivalent of the number line. || Location can change as a result of movement in space. | Change in location does not imply change in orientation.","skills_procedures":"Relate the axes of the Cartesian plane to intersecting horizontal and vertical representations of the number line. | Locate a point in the Cartesian plane, given the coordinates of the point. | Describe the location of a point in the Cartesian plane, using coordinates. | Model a polygon in the Cartesian plane, using coordinates to indicate the vertices. | Describe the location of the vertices of a polygon in the Cartesian plane, using coordinates. || Create an image of a polygon in the Cartesian plane by translating the polygon. | Describe the horizontal and vertical components of a given translation. | Create an image of a polygon in the Cartesian plane by reflecting the polygon over the x -axis or y -axis. | Describe the line of reflection of a given reflection, limited to reflection over the x -axis or y -axis. | Create an image of a polygon in the Cartesian plane by rotating the polygon 90°, 180°, or 270° about one of its vertices, clockwise or counter-clockwise. | Describe the angle and direction of a given rotation, limited to rotations of 90°, 180°, or 270° about a vertex. | Relate the coordinates of a polygon and its image after translation, reflection, or rotation in the Cartesian plane.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$MEA$txt$), 6, $txt$AB-G6-MEA-1$txt$, $txt$derived$txt$, $txt$MAT6-OI5-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students analyze areas of parallelograms and triangles.$txt$, $txt${"organizing_idea":"Measurement: Attributes such as length, area, volume, and angle are quantified by measurement.","guiding_question":"In what ways can shapes be related by using conservation of area?","knowledge":"A parallelogram is any quadrilateral with two pairs of parallel and equal sides. | Any side of a parallelogram can be interpreted as the base. | The height of a parallelogram is the perpendicular distance from its base to its opposite side. | The area of a triangle is half of the area of a parallelogram with the same base and height. | Two triangles with the same base and height must have the same area. || Area of composite shapes can be interpreted as the sum of the areas of multiple shapes, such as triangles and parallelograms.","understanding":"The area of a parallelogram can be generalized as the product of the perpendicular base and height. | The area of a triangle can be interpreted relative to the area of a parallelogram. || An area can be decomposed in infinitely many ways.","skills_procedures":"Rearrange the area of a parallelogram to form a rectangular area, using hands-on materials or digital applications. | Determine the area of a parallelogram, using multiplication. | Determine the base or height of a parallelogram, using division. | Model the area of a parallelogram as two congruent triangles. | Describe the relationship between the area of a triangle and the area of a parallelogram with the same base and height. | Determine the area of a triangle, including various triangles with the same base and height. | Solve problems involving the areas of parallelograms and triangles. || Visualize the decomposition of composite areas in various ways. | Determine the area of composite shapes, using the areas of triangles and parallelograms.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$MEA$txt$), 6, $txt$AB-G6-MEA-2$txt$, $txt$derived$txt$, $txt$MAT6-OI5-GQ2-LO1$txt$, $txt$outcome$txt$, null, $txt$Students interpret and express volume.$txt$, $txt${"organizing_idea":"Measurement: Attributes such as length, area, volume, and angle are quantified by measurement.","guiding_question":"How can volume characterize space?","knowledge":"Volume can be measured in non-standard units or standard units. | Volume can be expressed in the following standard units, derived from standard units of length: | cubic centimetres | cubic metres | A cubic centimetre (cm 3 ) is a volume equivalent to the volume of a cube measuring 1 centimetre by 1 centimetre by 1 centimetre. | A cubic metre (m 3 ) is a volume equivalent to the volume of a cube measuring 1 metre by 1 metre by 1 metre. | The volume of a right rectangular prism can be interpreted as the product of the two-dimensional base area and the perpendicular height of the prism.","understanding":"Volume is a measurable attribute that describes the amount of three-dimensional space occupied by a three-dimensional shape. | The volume of a prism can be interpreted as the result of perpendicular motion of an area. | Volume remains the same when decomposed or rearranged. | Volume is quantified by measurement. | Volume is measured with congruent units that themselves have volume and do not need to resemble the shape being measured. | The volume of a right rectangular prism can be perceived as cube-shaped units structured in a three-dimensional array.","skills_procedures":"Recognize volume in familiar contexts. | Model volume of prisms by dragging or iterating an area, using hands-on materials or digital applications. | Create a model of a three-dimensional shape by stacking congruent non-standard units or cubic centimetres without gaps or overlaps. | Express volume in non-standard units or cubic centimetres. | Visualize and model the volume of various right rectangular prisms as three-dimensional arrays of cube-shaped units. | Determine the volume of a right rectangular prism, using multiplication. | Solve problems involving volume of right rectangular prisms.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$PAT$txt$), 6, $txt$AB-G6-PAT-1$txt$, $txt$derived$txt$, $txt$MAT6-OI6-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students investigate functions to enhance understanding of change.$txt$, $txt${"organizing_idea":"Patterns: Awareness of patterns supports problem solving in various situations.","guiding_question":"How can a function enhance interpretation of change?","knowledge":"A variable can be interpreted as the values of a changing quantity. | A function can involve quantities that change over time, such as | height of a person or plant | temperature | distance travelled | A table of values lists the values of the independent variable in the first column or row and the values of the dependent variable in the second column or row to represent a function at certain points. | The values of the independent variable are represented by x -coordinates in the Cartesian plane. | The values of the dependent variable are represented by y -coordinates in the Cartesian plane.","understanding":"A function is a correspondence between two changing quantities represented by independent and dependent variables. | Each value of the independent variable in a function corresponds to exactly one value of the dependent variable.","skills_procedures":"Identify the dependent and independent variables in a given situation, including situations involving change over time. | Describe the rule that determines the values of the dependent variable from values of the independent variable. | Represent corresponding values of the independent and dependent variables of a function in a table of values and as points in the Cartesian plane. | Write an algebraic equation that represents a function. | Recognize various representations of the same function. | Determine a value of the dependent variable of a function, given the corresponding value of the independent variable. | Investigate strategies for determining a value of the independent variable of a function, given the corresponding value of the dependent variable. | Solve problems involving a function.","source_last_modified":"2026-08-17","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K6-2022$txt$) and code = $txt$STA$txt$), 6, $txt$AB-G6-STA-1$txt$, $txt$derived$txt$, $txt$MAT6-OI8-GQ1-LO1$txt$, $txt$outcome$txt$, null, $txt$Students investigate relative frequency, using experimental data.$txt$, $txt${"organizing_idea":"Statistics: The science of collecting, analyzing, visualizing, and interpreting data can inform understanding and decision making.","guiding_question":"How can frequency support communication?","knowledge":"Relative frequency can be used to compare the same category of data across multiple data sets. | Relative frequency can be represented in various forms. || Equally likely outcomes of an experiment have the same chance of occurring. | An event can be described as one or more outcomes of an experiment, including getting | a head when a coin is tossed | an even number when a die is rolled | blue when a spinner is spun | The law of large numbers states that more trials of an experiment result in a better estimate of the expected likelihood of an event.","understanding":"Relative frequency expresses the frequency of a category of data as a fraction of the total number of data values. || Frequency can be a count of categorized observations or trials in an experiment. | Relative frequency of outcomes can be used to estimate the likelihood of an event. | Relative frequency varies between sets of collected data. | Relative frequency provides a better estimate of the likelihood of an event with larger amounts of data.","skills_procedures":"Interpret frequency of categorized data as relative frequency. | Express relative frequencies as decimals, fractions, or percentages. || Identify the possible outcomes of an experiment involving equally likely outcomes. | Collect categorized data through experiments. | Predict the likelihood of an event based on the possible outcomes of an experiment. | Determine relative frequency for categories of a sample of data. | Describe the likelihood of an outcome in an experiment, using relative frequency. | Analyze relative frequency statistics from experiments with different sample sizes.","source_last_modified":"2025-11-28","source_data_url":"https://curriculum.learnalberta.ca/cdn/curriculum/gfc-mat.json"}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/curriculum/en/c/mat6$txt$, 15, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K9-2016$txt$) and code = $txt$N$txt$), 7, $txt$AB-G7-N-1$txt$, $txt$derived$txt$, null, $txt$outcome$txt$, null, $txt$Determine and explain why a number is divisible by 2, 3, 4, 5, 6, 8, 9 or 10, and why a number cannot be divided by 0.$txt$, $txt${"substrand":"","official_number":1,"processes":"C, R","note":"Alberta numbers specific outcomes within each strand per grade (e.g. Grade 7 Number SO 3). Key is derived from grade+strand+number. effective_from is the Masterasium tracking start, not the official implementation date."}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/cdn/assets/public/ef066215-6eae-5350-8ba0-f9fe82004ee8/mathematics-7-to-9.pdf$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K9-2016$txt$) and code = $txt$N$txt$), 7, $txt$AB-G7-N-2$txt$, $txt$derived$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of the addition, subtraction, multiplication and division of decimals to solve problems (for more than 1-digit divisors or 2-digit multipliers, the use of technology is expected).$txt$, $txt${"substrand":"","official_number":2,"processes":"ME, PS, T","note":"Alberta numbers specific outcomes within each strand per grade (e.g. Grade 7 Number SO 3). Key is derived from grade+strand+number. effective_from is the Masterasium tracking start, not the official implementation date."}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/cdn/assets/public/ef066215-6eae-5350-8ba0-f9fe82004ee8/mathematics-7-to-9.pdf$txt$, 2, false, $txt$2026-10-17$txt$::date),
