  ((select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K9-2016$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$AB-MATH-K9-2016$txt$) and code = $txt$N$txt$), 7, $txt$AB-G7-N-4$txt$, $txt$derived$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of the relationship between positive terminating decimals and positive fractions and between positive repeating decimals and positive fractions.$txt$, $txt${"substrand":"","official_number":4,"processes":"C, CN, R, T","note":"Alberta numbers specific outcomes within each strand per grade (e.g. Grade 7 Number SO 3). Key is derived from grade+strand+number. effective_from is the Masterasium tracking start, not the official implementation date."}$txt$::jsonb, $txt$https://curriculum.learnalberta.ca/cdn/assets/public/ef066215-6eae-5350-8ba0-f9fe82004ee8/mathematics-7-to-9.pdf$txt$, 4, false, $txt$2026-10-17$txt$::date),
